#[summary("Integer utility tasks: clamp of an i64 into a closed range.")]
mod tasks {
    #[effects(pure)]
    #[uses(clamp_result_ok, ordered)]
    fn clamp(x: i64, lo: i64, hi: i64) -> (r: i64)
        requires ordered(lo, hi),
        ensures clamp_result_ok(x, lo, hi, r),
    {
        if x < lo {
            lo
        } else if x > hi {
            hi
        } else {
            x
        }
    }

    spec fn clamp_result_ok(x: i64, lo: i64, hi: i64, r: i64) -> bool {
        (x < lo ==> r == lo) && (x > hi ==> r == hi) && (lo <= x && x <= hi ==> r == x)
    }

    spec fn ordered(lo: i64, hi: i64) -> bool {
        lo <= hi
    }
}

#[summary("Integer task implementations, including midpoint: floor of the mean of two i64 values without overflow.")]
mod tasks {
    spec fn floor_mid(a: i64, b: i64, r: i64) -> bool {
        2 * r <= a + b && a + b < 2 * r + 2
    }

    #[effects(pure)]
    #[uses(floor_mid)]
    fn midpoint(a: i64, b: i64) -> (r: i64)
        ensures floor_mid(a, b, r),
    {
        if (a < 0) == (b < 0) {
            let lo: i64 = if a <= b {
                a
            } else {
                b
            };
            let hi: i64 = if a <= b {
                b
            } else {
                a
            };
            let d: i64 = hi - lo;
            lo + d / 2
        } else {
            let s: i64 = a + b;
            if s >= 0 {
                s / 2
            } else {
                let u: i64 = s + 1;
                let t: i64 = 0 - u;
                0 - t / 2 - 1
            }
        }
    }
}

#[summary("Task implementations: saturating left-to-right sum of an i64 slice.")]
mod tasks {
    spec fn sat_add(s: i64, x: i64) -> i64 {
        if x > 0 && s > 9223372036854775807 - x {
            9223372036854775807
        } else if x < 0 && s < -9223372036854775807 - 1 - x {
            -9223372036854775807 - 1
        } else {
            s + x
        }
    }

    #[uses(sat_prefix)]
    spec fn sat_is(a: &[i64], r: i64) -> bool {
        sat_prefix(a, a.len()) == r
    }

    #[uses(sat_add)]
    spec fn sat_prefix(a: &[i64], n: usize) -> i64
        decreases n,
    {
        if n == 0 {
            0
        } else if n <= a.len() {
            sat_add(sat_prefix(a, n - 1), a[n - 1])
        } else {
            0
        }
    }

    #[effects(pure)]
    #[uses(sat_add, sat_is, sat_prefix)]
    fn sat_sum(a: &[i64]) -> (r: i64)
        ensures sat_is(a, r),
    {
        let mut s: i64 = 0;
        let mut i: usize = 0;
        while i < a.len()
            invariant i <= a.len(), s == sat_prefix(a, i),
            decreases a.len() - i,
        {
            let x: i64 = a[i];
            if x > 0 && s > 9223372036854775807 - x {
                s = 9223372036854775807;
            } else if x < 0 && s < -9223372036854775807 - 1 - x {
                s = -9223372036854775807 - 1;
            } else {
                s = s + x;
            }
            i = i + 1;
        }
        s
    }
}

#[summary("Counting helpers over i64 slices with inclusive range bounds.")]
mod tasks {
    #[effects(pure)]
    #[uses(count_prefix, counted_upto, counts_all)]
    fn count_in_range(a: &[i64], lo: i64, hi: i64) -> (r: usize)
        ensures counts_all(a, lo, hi, r),
    {
        let mut i: usize = 0;
        let mut count: usize = 0;
        while i < a.len()
            invariant counted_upto(a, lo, hi, i, count),
            decreases a.len() - i,
        {
            if lo <= a[i] && a[i] <= hi {
                count = count + 1;
            }
            i = i + 1;
        }
        count
    }

    spec fn count_prefix(a: &[i64], lo: i64, hi: i64, n: usize) -> usize
        decreases n,
    {
        if n == 0 || n > a.len() {
            0
        } else if lo <= a[n - 1] && a[n - 1] <= hi {
            1 + count_prefix(a, lo, hi, n - 1)
        } else {
            count_prefix(a, lo, hi, n - 1)
        }
    }

    #[uses(count_prefix)]
    spec fn counted_upto(a: &[i64], lo: i64, hi: i64, i: usize, count: usize) -> bool {
        i <= a.len() && count <= i && count == count_prefix(a, lo, hi, i)
    }

    #[uses(count_prefix)]
    spec fn counts_all(a: &[i64], lo: i64, hi: i64, r: usize) -> bool {
        r == count_prefix(a, lo, hi, a.len())
    }
}

#[summary("Index-of-first-maximum task for non-empty i64 slices.")]
mod tasks {
    #[effects(pure)]
    #[uses(is_first_max, non_empty)]
    fn first_max_index(a: &[i64]) -> (r: usize)
        requires non_empty(a),
        ensures is_first_max(a, r),
    {
        let mut best: usize = 0;
        let mut i: usize = 1;
        while i < a.len()
            invariant i <= a.len(), best < i, forall|k: usize| k < i ==> #[trigger] a[k] <= a[best], forall|m: usize| m < best ==> #[trigger] a[m] < a[best],
            decreases a.len() - i,
        {
            if a[i] > a[best] {
                best = i;
            }
            i = i + 1;
        }
        best
    }

    spec fn is_first_max(a: &[i64], r: usize) -> bool {
        r < a.len() && (forall|i: usize| i < a.len() ==> #[trigger] a[i] <= a[r]) && (forall|j: usize| j < r ==> #[trigger] a[j] < a[r])
    }

    spec fn non_empty(a: &[i64]) -> bool {
        a.len() > 0
    }
}

#[summary("Index-finding tasks over i64 slices, including the last position of a minimum.")]
mod tasks {
    spec fn is_last_min(a: &[i64], r: usize) -> bool {
        r < a.len() && (forall|j: usize| j < a.len() ==> #[trigger] a[j] >= a[r]) && (forall|k: usize| k < a.len() && k > r ==> #[trigger] a[k] > a[r])
    }

    #[effects(pure)]
    #[uses(is_last_min, non_empty)]
    fn last_min_index(a: &[i64]) -> (r: usize)
        requires non_empty(a),
        ensures is_last_min(a, r),
    {
        let mut best: usize = 0;
        let mut i: usize = 1;
        while i < a.len()
            invariant 1 <= i, i <= a.len(), best < i, forall|j: usize| j < i ==> #[trigger] a[j] >= a[best], forall|k: usize| k < i && k > best ==> #[trigger] a[k] > a[best],
            decreases a.len() - i,
        {
            if a[i] <= a[best] {
                best = i;
            }
            i = i + 1;
        }
        best
    }

    spec fn non_empty(a: &[i64]) -> bool {
        a.len() > 0
    }
}

#[summary("Small list checks over i64 slices.")]
mod tasks {
    spec fn matches_result(a: &[i64], r: bool) -> bool {
        r == strictly_sorted(a)
    }

    spec fn pairs_ok(a: &[i64], k: usize) -> bool {
        forall|j: usize| j < k && j + 1 < a.len() ==> #[trigger] a[j] < a[j + 1]
    }

    #[effects(pure)]
    #[uses(matches_result, pairs_ok, strictly_sorted)]
    fn strictly_increasing(a: &[i64]) -> (r: bool)
        ensures matches_result(a, r),
    {
        let n: usize = a.len();
        let mut i: usize = 0;
        let mut ok: bool = true;
        while i + 1 < n
            invariant i <= n, n == a.len(), ok == pairs_ok(a, i),
            decreases n - i,
        {
            ok = ok && a[i] < a[i + 1];
            i = i + 1;
        }
        ok
    }

    spec fn strictly_sorted(a: &[i64]) -> bool {
        pairs_ok(a, a.len())
    }
}

#[summary("Binary-search helpers for sorted i64 slices.")]
mod tasks {
    spec fn above(a: &[i64], t: i64, hi: usize) -> bool {
        hi < a.len() ==> a[hi] >= t
    }

    spec fn below(a: &[i64], t: i64, lo: usize) -> bool {
        forall|k: usize| k < lo && k < a.len() ==> #[trigger] a[k] < t
    }

    #[effects(pure)]
    #[uses(above, below, result_ok, sorted)]
    fn lower_bound(a: &[i64], t: i64) -> (r: usize)
        requires sorted(a),
        ensures result_ok(a, t, r),
    {
        let mut lo: usize = 0;
        let mut hi: usize = a.len();
        while lo < hi
            invariant lo <= hi, hi <= a.len(), below(a, t, lo), above(a, t, hi),
            decreases hi - lo,
        {
            let mid: usize = lo + (hi - lo) / 2;
            if a[mid] < t {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        lo
    }

    spec fn result_ok(a: &[i64], t: i64, r: usize) -> bool {
        r <= a.len() && below(a, t, r) && above(a, t, r)
    }

    spec fn sorted(a: &[i64]) -> bool {
        forall|i: usize, j: usize| i <= j && j < a.len() ==> #[trigger] (a[i] <= a[j])
    }
}

#[summary("Integer tasks: floor division rounding toward negative infinity.")]
mod tasks {
    #[effects(pure)]
    #[uses(div_floor_post, div_floor_pre)]
    fn div_floor(a: i64, b: i64) -> (r: i64)
        requires div_floor_pre(a, b),
        ensures div_floor_post(a, b, r),
    {
        let q: i64 = a / b;
        let m: i64 = a % b;
        if m < 0 && b > 0 || m > 0 && b < 0 {
            q - 1
        } else {
            q
        }
    }

    spec fn div_floor_post(a: i64, b: i64, r: i64) -> bool {
        if b > 0 {
            r * b <= a && a < (r + 1) * b
        } else {
            (r + 1) * b < a && a <= r * b
        }
    }

    spec fn div_floor_pre(a: i64, b: i64) -> bool {
        b != 0 && !(a == -9223372036854775807 - 1 && b == -1)
    }
}

#[summary("Integer helper tasks: floor modulus a - b*floor(a/b) for i64 with b != 0.")]
mod tasks {
    spec fn divisor_is_minus_one(b: i64) -> bool {
        b == -1
    }

    spec fn divisor_not_minus_one(b: i64) -> bool {
        b != 0 && b != -1
    }

    spec fn divisor_ok(b: i64) -> bool {
        b != 0
    }

    spec fn floor_mod_congruent_ok(a: i64, b: i64, r: i64) -> bool {
        (a - r) % b == 0
    }

    spec fn floor_mod_ok(a: i64, b: i64, r: i64) -> bool {
        (b > 0 && 0 <= r && r < b || b < 0 && b < r && r <= 0) && (a - r) % b == 0
    }

    spec fn floor_mod_range_ok(b: i64, r: i64) -> bool {
        r == 0 || b > 0 && 0 <= r && r < b || b < 0 && b < r && r <= 0
    }

    #[effects(pure)]
    #[uses(divisor_is_minus_one, floor_mod_congruent_ok, zero_remainder_ok)]
    fn minus_one_rem(a: i64, b: i64) -> (r: i64)
        requires divisor_is_minus_one(b),
        ensures zero_remainder_ok(r), floor_mod_congruent_ok(a, b, r),
    {
        0
    }

    #[effects(pure)]
    #[uses(divisor_is_minus_one, divisor_not_minus_one, divisor_ok, floor_mod_congruent_ok, floor_mod_range_ok, zero_remainder_ok)]
    fn mod_floor(a: i64, b: i64) -> (r: i64)
        requires divisor_ok(b),
        ensures floor_mod_range_ok(b, r), floor_mod_congruent_ok(a, b, r),
    {
        if b == -1 {
            minus_one_rem(a, b)
        } else {
            let t: i64 = trunc_rem(a, b);
            shift_to_floor(a, b, t)
        }
    }

    spec fn neg_div_pos_rem(b: i64, t: i64) -> bool {
        b < 0 && t > 0
    }

    spec fn neg_floor_range(b: i64, r: i64) -> bool {
        b < r && r <= 0
    }

    spec fn pos_div_neg_rem(b: i64, t: i64) -> bool {
        b > 0 && t < 0
    }

    spec fn pos_floor_range(b: i64, r: i64) -> bool {
        0 <= r && r < b
    }

    #[effects(pure)]
    #[uses(divisor_not_minus_one, floor_mod_congruent_ok, neg_div_pos_rem, neg_floor_range, trunc_rem_ok)]
    fn shift_neg_case(a: i64, b: i64, t: i64) -> (r: i64)
        requires divisor_not_minus_one(b), neg_div_pos_rem(b, t), trunc_rem_ok(b, t), floor_mod_congruent_ok(a, b, t),
        ensures neg_floor_range(b, r), floor_mod_congruent_ok(a, b, r),
    {
        t + b
    }

    #[effects(pure)]
    #[uses(divisor_not_minus_one, floor_mod_congruent_ok, pos_div_neg_rem, pos_floor_range, trunc_rem_ok)]
    fn shift_pos_case(a: i64, b: i64, t: i64) -> (r: i64)
        requires divisor_not_minus_one(b), pos_div_neg_rem(b, t), trunc_rem_ok(b, t), floor_mod_congruent_ok(a, b, t),
        ensures pos_floor_range(b, r), floor_mod_congruent_ok(a, b, r),
    {
        t + b
    }

    #[effects(pure)]
    #[uses(divisor_not_minus_one, floor_mod_congruent_ok, floor_mod_range_ok, neg_div_pos_rem, neg_floor_range, pos_div_neg_rem, pos_floor_range, trunc_rem_ok)]
    fn shift_to_floor(a: i64, b: i64, t: i64) -> (r: i64)
        requires divisor_not_minus_one(b), trunc_rem_ok(b, t), floor_mod_congruent_ok(a, b, t),
        ensures floor_mod_range_ok(b, r), floor_mod_congruent_ok(a, b, r),
    {
        if t < 0 && b > 0 {
            shift_pos_case(a, b, t)
        } else {
            if t > 0 && b < 0 {
                shift_neg_case(a, b, t)
            } else {
                t
            }
        }
    }

    #[effects(pure)]
    #[uses(divisor_not_minus_one, floor_mod_congruent_ok, trunc_rem_ok)]
    fn trunc_rem(a: i64, b: i64) -> (t: i64)
        requires divisor_not_minus_one(b),
        ensures trunc_rem_ok(b, t), floor_mod_congruent_ok(a, b, t),
    {
        a % b
    }

    spec fn trunc_rem_ok(b: i64, t: i64) -> bool {
        t == 0 || b > 0 && -b < t && t < b || b < 0 && b < t && t < -b
    }

    spec fn zero_remainder_ok(r: i64) -> bool {
        r == 0
    }
}

#[summary("Task solutions: maximum contiguous subarray sum (Kadane over prefix sums).")]
mod tasks {
    spec fn attained(a: &[i64], r: i64) -> bool {
        !(forall|p: usize, q: usize| p < q && q <= a.len() ==> #[trigger] seg(a, p, q) != r)
    }

    spec fn dominates(a: &[i64], r: i64) -> bool {
        forall|i: usize, j: usize| i < j && j <= a.len() ==> #[trigger] seg(a, i, j) <= r
    }

    spec fn elems_ok(a: &[i64]) -> bool {
        1 <= a.len() && a.len() <= 1000000 && (forall|k: usize| k < a.len() ==> -1000000000 <= #[trigger] a[k] && a[k] <= 1000000000)
    }

    #[effects(pure)]
    #[uses(attained, dominates, elems_ok, pre, seg)]
    fn max_subarray(a: &[i64]) -> (r: i64)
        requires elems_ok(a),
        ensures dominates(a, r), attained(a, r),
    {
        let n: usize = a.len();
        let mut p: i64 = a[0];
        let mut mn: i64 = 0;
        let mut mi: usize = 0;
        let mut best: i64 = a[0];
        let mut bi: usize = 0;
        let mut bj: usize = 1;
        let mut j: usize = 1;
        while j < n
            invariant elems_ok(a), n == a.len(), 1 <= j, j <= n, p == pre(a, j), p <= 1000000000 * j, -1000000000 * j <= p, mi < j, mn == pre(a, mi), -1000000000 * j <= mn, mn <= 1000000000 * j, forall|s: usize| s < j ==> #[trigger] pre(a, s) >= mn, bi < bj, bj <= j, best == seg(a, bi, bj), forall|u: usize, v: usize| u < v && v <= j ==> #[trigger] seg(a, u, v) <= best,
            decreases n - j,
        {
            let aj: i64 = a[j];
            let p2: i64 = p + aj;
            if p < mn {
                mn = p;
                mi = j;
            }
            let cand: i64 = p2 - mn;
            if cand > best {
                best = cand;
                bi = mi;
                bj = j + 1;
            }
            p = p2;
            j = j + 1;
        }
        best
    }

    spec fn pre(a: &[i64], j: usize) -> i64
        decreases j,
    {
        if j == 0 {
            0
        } else if j <= a.len() {
            pre(a, j - 1) + a[j - 1]
        } else {
            0
        }
    }

    spec fn seg(a: &[i64], i: usize, j: usize) -> i64 {
        pre(a, j) - pre(a, i)
    }
}

#[summary("Second largest distinct value of a slice of i64, or i64::MIN when there are fewer than two distinct values.")]
mod tasks {
    #[effects(pure)]
    #[uses(second_ok)]
    fn second_max(a: &[i64]) -> (r: i64)
        ensures second_ok(a, r),
    {
        let mut m: i64 = i64::MIN;
        let mut i: usize = 0;
        while i < a.len()
            invariant i <= a.len(), forall|j1: usize| j1 < i ==> #[trigger] a[j1] <= m, m == i64::MIN || !(forall|k1: usize| k1 < i ==> #[trigger] a[k1] != m),
            decreases a.len() - i,
        {
            if a[i] > m {
                m = a[i];
            }
            i = i + 1;
        }
        let mut best: i64 = i64::MIN;
        let mut t: usize = 0;
        while t < a.len()
            invariant t <= a.len(), forall|j2: usize| j2 < a.len() ==> #[trigger] a[j2] <= m, m == i64::MIN || !(forall|k2: usize| k2 < a.len() ==> #[trigger] a[k2] != m), best == i64::MIN || !(forall|k3: usize| k3 < a.len() ==> #[trigger] a[k3] != best) && best < m, forall|j3: usize| j3 < t && #[trigger] a[j3] < m ==> a[j3] <= best,
            decreases a.len() - t,
        {
            if a[t] < m && a[t] > best {
                best = a[t];
            }
            t = t + 1;
        }
        best
    }

    spec fn second_ok(a: &[i64], r: i64) -> bool {
        (r == i64::MIN || !(forall|k: usize| k < a.len() ==> #[trigger] a[k] != r)) && (forall|j: usize| j < a.len() && #[trigger] a[j] > r ==> (forall|k2: usize| k2 < a.len() && #[trigger] a[k2] > r ==> a[k2] == a[j])) && ((forall|k3: usize| k3 < a.len() ==> #[trigger] a[k3] <= r) ==> r == i64::MIN)
    }
}

#[summary("Cyclic rotation of an i64 slice to the right by k positions, in place.")]
mod tasks {
    spec fn idx_ok(a: &[i64], x: usize, y: usize) -> bool {
        x < a.len() && y < a.len()
    }

    #[effects(pure)]
    #[uses(rot_le, rot_pos, rot_r)]
    fn mk_r(k: usize, n: usize) -> (r: usize)
        requires rot_pos(n),
        ensures rot_r(k, n, r), rot_le(r, n),
    {
        k % n
    }

    spec fn parts_ok(a: &[i64], mid: &[i64], n: usize, r: usize) -> bool {
        a.len() == mid.len() && n == a.len() && r <= n && (forall|p: usize| p < a.len() ==> #[trigger] a[p] == mid[if p < r { r - 1 - p } else { r + (n - 1 - p) }])
    }

    spec fn rev_loop(a: &[i64], orig: &[i64], lo: usize, i: usize, j: usize, hi: usize) -> bool {
        a.len() == orig.len() && lo <= i && i <= hi && j <= hi && lo <= j && hi <= a.len() && i + j == lo + hi && (forall|p: usize| p < a.len() ==> #[trigger] a[p] == orig[if lo <= p && p < hi && (p < i || j <= p) { lo + (hi - 1 - p) } else { p }])
    }

    spec fn rev_span(a: &[i64], orig: &[i64], lo: usize, hi: usize) -> bool {
        a.len() == orig.len() && lo <= hi && hi <= a.len() && (forall|p: usize| p < a.len() ==> #[trigger] a[p] == orig[if lo <= p && p < hi { lo + (hi - 1 - p) } else { p }])
    }

    #[effects(pure)]
    #[uses(idx_ok, rev_loop, rev_span, span_ok, swapped)]
    fn reverse(a: &mut [i64], lo: usize, hi: usize) -> ()
        requires span_ok(a, lo, hi),
        ensures rev_span(a, old(a), lo, hi),
    {
        let mut i: usize = lo;
        let mut j: usize = hi;
        while i < j
            invariant rev_loop(a, old(a), lo, i, j, hi),
            decreases j - i,
        {
            swap_at(a, i, j - 1);
            i = i + 1;
            j = j - 1;
        }
    }

    spec fn rot_args(a: &[i64], n: usize, r: usize) -> bool {
        n == a.len() && r <= n
    }

    spec fn rot_form(a: &[i64], orig: &[i64], n: usize, r: usize) -> bool {
        a.len() == orig.len() && n == a.len() && r <= n && (forall|p: usize| p < a.len() ==> #[trigger] a[p] == orig[if p < r { n - r + p } else { p - r }])
    }

    spec fn rot_le(r: usize, n: usize) -> bool {
        r <= n
    }

    #[uses(shifted)]
    spec fn rot_partial(a: &[i64], orig: &[i64], k: usize, i: usize) -> bool {
        a.len() == orig.len() && i <= a.len() && (forall|p: usize| p < i ==> #[trigger] a[shifted(p, k, a.len())] == orig[p])
    }

    #[effects(pure)]
    #[uses(parts_ok, rev_span, rot_args, span_ok)]
    fn rot_parts(a: &mut [i64], n: usize, r: usize) -> ()
        requires rot_args(a, n, r),
        ensures parts_ok(a, old(a), n, r),
    {
        reverse(a, r, n);
        reverse(a, 0, r);
    }

    spec fn rot_pos(n: usize) -> bool {
        n > 0 && n <= 9223372036854775807
    }

