#[summary("Majority element: value occurring strictly more than a.len() / 2 times, else i64::MIN")]
mod tasks {
    #[uses(no_majority, occ)]
    spec fn answer(a: &[i64], r: i64) -> bool {
        occ(a, r, a.len()) > a.len() / 2 || r == i64::MIN && no_majority(a)
    }

    #[uses(occ)]
    spec fn bm_inv(a: &[i64], cand: i64, cnt: usize, i: usize) -> bool {
        cnt <= i && i <= a.len() && (forall|v: i64| v != cand ==> #[trigger] occ(a, v, i) * 2 + cnt <= i && occ(a, cand, i) * 2 <= i + cnt)
    }

