    #[uses(bm_inv, is_cand, occ)]
    fn bm_scan(a: &[i64]) -> (r: i64)
        ensures is_cand(a, r),
    {
        let mut cand: i64 = 0;
        let mut cnt: usize = 0;
        let mut i: usize = 0;
        while i < a.len()
            invariant bm_inv(a, cand, cnt, i), i <= a.len(),
            decreases a.len() - i,
        {
            let x: i64 = a[i];
            if cnt == 0 {
                cand = x;
                cnt = 1;
            } else if x == cand {
                cnt = cnt + 1;
            } else {
                cnt = cnt - 1;
            }
            i = i + 1;
        }
        cand
    }

    #[uses(occ)]
    spec fn is_cand(a: &[i64], cand: i64) -> bool {
        forall|v: i64| #[trigger] occ(a, v, a.len()) * 2 > a.len() ==> v == cand
    }

    #[effects(pure)]
    #[uses(answer, is_cand, no_majority, occ)]
    fn majority(a: &[i64]) -> (r: i64)
        ensures answer(a, r),
    {
        let cand: i64 = bm_scan(a);
        let mut c: usize = 0;
        let mut j: usize = 0;
        while j < a.len()
            invariant j <= a.len(), c <= j, c == occ(a, cand, j),
            decreases a.len() - j,
        {
            if a[j] == cand {
                c = c + 1;
            }
            j = j + 1;
        }
        if c > a.len() / 2 {
            cand
        } else {
            i64::MIN
        }
    }

    #[uses(occ)]
    spec fn no_majority(a: &[i64]) -> bool {
        forall|v: i64| #[trigger] occ(a, v, a.len()) <= a.len() / 2
    }

    #[uses(occ)]
    spec fn occ(a: &[i64], v: i64, n: usize) -> i64
        decreases n,
    {
        if n == 0 {
            0
        } else if a[n - 1] == v {
