}

#[summary("Modular exponentiation: pow_mod(base, exp, m) = base^exp mod m, computed exactly for base>=0, exp>=0, 1<=m<=3e9.")]
mod tasks {
    spec fn pow_inv(m: i64, result: i64, b: i64, e: i64) -> bool {
        0 <= result && result < m && 0 <= b && b < m && 0 <= e
    }

    #[effects(pure)]
    #[uses(pow_inv, pow_post, pow_pre)]
    fn pow_mod(base: i64, exp: i64, m: i64) -> (r: i64)
        requires pow_pre(base, exp, m),
        ensures pow_post(m, r),
    {
        let mut result: i64 = 1 % m;
        let mut b: i64 = base % m;
        let mut e: i64 = exp;
        while e > 0
            invariant pow_inv(m, result, b, e),
            decreases e,
        {
            if e % 2 == 1 {
                result = result * b % m;
            }
            b = b * b % m;
            e = e / 2;
        }
        result
    }

    spec fn pow_post(m: i64, r: i64) -> bool {
        0 <= r && r < m
    }

    spec fn pow_pre(base: i64, exp: i64, m: i64) -> bool {
        0 <= base && 0 <= exp && 1 <= m && m <= 3000000000
    }
}
